models=[]
models.append(dict(id='fig-0002',title='Investment fund, fund class and processing characteristics',nodes=ns('Asset AssetClassification Security SecuritiesQuantity SecuritiesRelatedFees InvestmentFundFamily UmbrellaFund InvestmentFund InvestmentFundClass InvestmentFundClassProcessingCharacteristics TimeFrame',{'Security':'Securities','InvestmentFundClass':'Securities','UmbrellaFund':'Securities','InvestmentFundClassProcessingCharacteristics':'Securities','SecuritiesRelatedFees':'DICO_BusinessComponents','InvestmentFundFamily':'DICO_BusinessComponents','InvestmentFund':'DICO_BusinessComponents'}),edges=[e('Asset','AssetClassification'),inherit('Security','Asset'),e('SecuritiesQuantity','Security','- MinimumQuantity / + MinimumQuantityDebt'),e('Security','SecuritiesRelatedFees','+ Fees'),e('InvestmentFundFamily','InvestmentFund','+ Family'),e('UmbrellaFund','InvestmentFund','+ SubFund'),e('InvestmentFund','InvestmentFundClass'),inherit('InvestmentFundClass','Security'),e('InvestmentFundClass','InvestmentFundClassProcessingCharacteristics','+ FundClass / + ProcessingCharacteristics'),e('InvestmentFundClassProcessingCharacteristics','TimeFrame','- RelatedProcessingCharacteristics / - DealingCutOffTimeFrame'),e('InvestmentFundClassProcessingCharacteristics','TimeFrame','+ SubscriptionSettlementRelatedFundProcessing / + SettlementCycle')],meaning='Fund family and umbrella fund each link InvestmentFund, which links InvestmentFundClass. Fund class specializes Security; Security specializes Asset. Security also links minimum quantity and fees. Fund class connects processing characteristics, and two distinct associations connect those characteristics to TimeFrame: dealing cut-off and settlement cycle. Package labels appear only on some source nodes and are preserved only where printed.'))
models.append(dict(id='fig-0003',title='Investment-fund orders, executions and plans',nodes=ns('UmbrellaFund InvestmentFundFamily InvestmentFund Security InvestmentFundClass NetAssetValueCalculation PerformanceFactors ValuationStatistics InvestmentFundTransaction SecuritiesTradeExecution InvestmentFundOrder InvestmentFundOrderExecution RedemptionOrder SubscriptionOrder SwitchOrder RedemptionExecution SubscriptionExecution SwitchExecution SwitchRedemptionLeg SwitchSubscriptionLeg SwitchExecutionRedemptionLeg SwitchExecutionSubscriptionLeg TaxEfficientProduct InvestmentPlan Pension Asset Drawdown CappedLimit'),edges=[e('UmbrellaFund','InvestmentFund','+ SubFund'),e('InvestmentFundFamily','InvestmentFund','+ Family'),e('InvestmentFund','InvestmentFundClass'),inherit('InvestmentFundClass','Security'),e('InvestmentFundClass','NetAssetValueCalculation'),e('NetAssetValueCalculation','PerformanceFactors'),e('NetAssetValueCalculation','ValuationStatistics'),e('InvestmentFundClass','InvestmentFundTransaction','+ InvestmentFundClass'),e('InvestmentFundTransaction','InvestmentFundOrder'),e('InvestmentFundTransaction','InvestmentFundOrderExecution'),e('InvestmentFundOrder','InvestmentFundOrderExecution','+ Order'),inherit('InvestmentFundOrderExecution','SecuritiesTradeExecution'),inherit('RedemptionOrder','InvestmentFundOrder'),inherit('SubscriptionOrder','InvestmentFundOrder'),inherit('SwitchOrder','InvestmentFundOrder'),inherit('SwitchRedemptionLeg','RedemptionOrder'),inherit('SwitchSubscriptionLeg','SubscriptionOrder'),e('SwitchOrder','SwitchRedemptionLeg','+ RedemptionRelatedSwitchOrder / + RedemptionLeg'),e('SwitchOrder','SwitchSubscriptionLeg','+ SubscriptionRelatedSwitchOrder / + SubscriptionLeg'),inherit('RedemptionExecution','InvestmentFundOrderExecution'),inherit('SubscriptionExecution','InvestmentFundOrderExecution'),inherit('SwitchExecution','InvestmentFundOrderExecution'),inherit('SwitchExecutionRedemptionLeg','RedemptionExecution'),inherit('SwitchExecutionSubscriptionLeg','SubscriptionExecution'),e('SwitchExecution','SwitchExecutionRedemptionLeg','+ RedemptionLeg'),e('SwitchExecution','SwitchExecutionSubscriptionLeg','+ SubscriptionLeg'),e('SubscriptionExecution','TaxEfficientProduct','- CurrentYearSubscription'),e('TaxEfficientProduct','InvestmentPlan','- RelatedInvestmentPlan'),e('InvestmentPlan','Pension','- RelatedInvestmentPlan'),e('InvestmentPlan','Asset'),e('Pension','Drawdown'),e('Drawdown','CappedLimit','- RelatedDrawdown')],meaning='InvestmentFundClass links fund, net asset value calculation and investment-fund transaction. Order and order execution each connect that transaction; execution specializes securities trade execution. Redemption, subscription and switch orders specialize investment-fund order; their corresponding executions specialize investment-fund order execution. Switch legs have both their explicit parent generalization and separate switch association. Subscription execution links tax-efficient product, then investment plan, pension, drawdown and capped limit; the plan also links an asset. The figure supplies no package names or business-message direction.'))
packages={'SecuritiesPricing':'DICO_BusinessComponents','Security':'Securities','Tax':'DICO_BusinessComponents','InvestmentFundClass':'Securities','NetAssetValueCalculation':'Securities','ValuationStatistics':'DICO_BusinessComponents','FundsCashFlow':'DICO_BusinessComponents','SecuritiesQuantity':'DICO_BusinessComponents','Interest':'DICO_BusinessComponents','PerformanceFactors':'DICO_BusinessComponents','DateTimePeriod':'DICO_BusinessComponentsDataTypes'}
models.append(dict(id='fig-0004',title='Net asset value calculation and valuation context',nodes=ns('SecuritiesPricing Security Tax InvestmentFundClassProcessingCharacteristics InvestmentFundClass NetAssetValueCalculation ValuationStatistics FundsCashFlow SecuritiesQuantity Interest PerformanceFactors DateTimePeriod',packages),edges=[e('SecuritiesPricing','Security','+ Pricing'),e('SecuritiesPricing','NetAssetValueCalculation','+ Price'),e('SecuritiesPricing','ValuationStatistics','- PriceChange / - HighestPriceValue / - LowestPriceValue / + LowestPriceValueRelatedStatistics / + HighestPriceValueRelatedStatistics / + PriceChangeRelatedStatistics'),inherit('InvestmentFundClass','Security'),e('InvestmentFundClassProcessingCharacteristics','InvestmentFundClass','+ ProcessingCharacteristics / + FundClass'),e('InvestmentFundClass','NetAssetValueCalculation','- RelatedFund'),e('NetAssetValueCalculation','Tax','+ TaxRefundValueCalculation / + TaxRefund'),e('NetAssetValueCalculation','Tax','+ TaxLiabilityValueCalculation / + TaxLiability'),e('NetAssetValueCalculation','FundsCashFlow','+ FundsCashFlow'),e('NetAssetValueCalculation','SecuritiesQuantity'),e('NetAssetValueCalculation','Interest'),e('NetAssetValueCalculation','ValuationStatistics'),e('NetAssetValueCalculation','PerformanceFactors','+ InvestmentFundPerformanceFactors'),e('PerformanceFactors','DateTimePeriod','- AccumulationPeriod')],meaning='Net asset value calculation connects fund class, price, valuation statistics, tax-refund and tax-liability calculations as two separate tax associations, cash flow, quantity, interest and performance factors. Performance factors connect an accumulation period. The pricing-to-valuation-statistics line carries three labels at each end: they remain one visible line with all six labels, not six fabricated lines. InvestmentFundClass specializes Security and links processing characteristics.'))
models.append(dict(id='fig-0005',title='Investment-account contracts, services and party status',nodes=ns('AccountContract AccountService Account CashAccount InvestmentAccount SecuritiesAccount SidePocket InvestmentFundTax InvestmentAccountPartyRole InvestmentAccountService Reinvestment InvestmentPlan InvestmentAccountContract CRSStatus FATCAStatus',{'InvestmentAccountPartyRole':'DICO_BusinessComponents','CRSStatus':'DICO_BusinessComponents','FATCAStatus':'DICO_BusinessComponents'}),edges=[inherit('CashAccount','Account'),inherit('InvestmentAccount','Account'),inherit('SecuritiesAccount','Account'),inherit('InvestmentAccountService','AccountService'),inherit('InvestmentAccountContract','AccountContract'),e('AccountContract','Account'),e('AccountContract','AccountService'),e('AccountService','Account'),e('CashAccount','InvestmentAccount'),e('InvestmentAccount','SecuritiesAccount'),e('InvestmentAccount','SidePocket'),e('InvestmentAccount','InvestmentFundTax'),e('InvestmentAccount','InvestmentAccountPartyRole'),e('InvestmentAccount','InvestmentAccountContract'),e('InvestmentAccountService','InvestmentAccountContract'),e('InvestmentAccountService','Reinvestment'),e('InvestmentAccountService','InvestmentPlan','+ SystematicInvestmentPlan'),e('InvestmentAccountPartyRole','CRSStatus','+ InvestmentAccountParty'),e('InvestmentAccountPartyRole','FATCAStatus')],meaning='CashAccount, InvestmentAccount and SecuritiesAccount specialize Account. The account-contract-service triangle is retained. InvestmentAccountContract and InvestmentAccountService specialize their respective general concepts and connect investment account, reinvestment and systematic investment plan. Investment account links side pocket, investment-fund tax and investment-account party role. That role separately links CRSStatus and FATCAStatus. Tax-status associations do not identify a fixed institution or imply an account owner/servicer equivalence.'))
packages={'Role':'DICO_BusinessComponents','InvestmentFundPartyRole':'DICO_BusinessComponents','AccountPartyRole':'DICO_BusinessComponents','Account':'DICO_BusinessComponents','InvestmentAccountPartyRole':'DICO_BusinessComponents','InvestmentAccount':'DICO_BusinessComponents','Auditor':'Securities','FundManagerRole':'Securities','PlacementAgent':'DICO_BusinessCompon... (source label truncated)','Settlor':'DICO_BusinessComponents','FundAdministratorRole':'Securities','Grantor':'DICO_BusinessComponents','FundAccountantRole':'Securities','FundPromoter':'Securities','LegalGuardianRole':'Securities','TrusteeRole':'DICO_BusinessComponents','AdministratorRole':'DICO_BusinessComponents','Nominee':'DICO_BusinessComponents'}
names='Role AssetPartyRole GuaranteePartyRole IssuerRole GuarantorRole InvestmentFundPartyRole InvestmentFund AccountPartyRole Account InvestmentAccountPartyRole InvestmentAccount FundOrderDesk Auditor FundManagerRole PlacementAgent Settlor FundAdministratorRole Grantor FundAccountantRole FundPromoter LegalGuardianRole TrusteeRole AdministratorRole Nominee'
edges=[inherit(n,'Role') for n in ['AssetPartyRole','GuaranteePartyRole','InvestmentFundPartyRole','AccountPartyRole']]+[inherit('IssuerRole','AssetPartyRole'),inherit('GuarantorRole','GuaranteePartyRole')]+[inherit(n,'InvestmentFundPartyRole') for n in ['FundOrderDesk','Auditor','FundManagerRole','PlacementAgent','Settlor','FundAdministratorRole','Grantor','FundAccountantRole']]+[inherit('FundPromoter','FundManagerRole'),inherit('InvestmentAccountPartyRole','AccountPartyRole')]+[inherit(n,'InvestmentAccountPartyRole') for n in ['LegalGuardianRole','TrusteeRole','AdministratorRole','Nominee']]+[inherit('InvestmentAccount','Account'),e('InvestmentFund','InvestmentFundPartyRole','+ PartyRole'),e('AccountPartyRole','Account','+ PartyRole')]
models.append(dict(id='fig-0006',title='Investment-fund and investment-account party-role hierarchy',nodes=ns(names,packages),edges=edges,meaning='Role generalizes asset, guarantee, fund and account party roles. Issuer and guarantor specialize the corresponding asset/guarantee roles. The fund-party hierarchy includes fund order desk, auditor, fund manager, placement agent, settlor, fund administrator, grantor and fund accountant; fund promoter further specializes fund manager. Investment-account party role specializes account party role, with legal guardian, trustee, administrator and nominee subtypes. Account and InvestmentAccount have their own entity hierarchy, separate from roles. PartyRole associations link the fund and account entities to the respective contextual role. These generalizations do not equate roles with particular institutions.',limitations=['The PlacementAgent package label is visibly truncated in the supplied artwork as DICO_BusinessCompon...; its complete package spelling is not inferred.']))
for m in models:
 code='classDiagram\ndirection TB\n'
 for n in m['nodes']:code+='class '+n['id']+' {\n<<'+n['stereotype']+'>>\n}\n'
 for r in m['edges']:code+=r['a']+' '+r['kind']+' '+r['b']+(' : '+r['label'] if r['label'] else '')+'\n'
 m.update(source_id=SID,source=DIAGS[m['id']],mermaid=code,render_prefix=SID+'-'+m['id'],review_status='needs-review',package_note='The entity register preserves every visible package label, including explicitly absent or truncated labels. Package names are recorded there rather than adding enclosing boxes absent from the source.');m.setdefault('limitations',[])
 write(ROOT,OUT/(m['render_prefix']+'.mmd'),code,JOB)
write(ROOT,OUT/'models.json',json.dumps(models,ensure_ascii=False,indent=2),JOB)
print(json.dumps([{'id':m['id'],'nodes':len(m['nodes']),'edges':len(m['edges'])} for m in models]))
